// The texture-stage combiner (docs/graphics-backend.md section 10): Direct3D 8's texture stages as the game's
// shader classes set them up (bgfx_combiner.cpp, bgfx_shader.cpp), then the specular colour, the alpha test and
// linear table fog. Included by
//   - fs_cmb_<key hash>.sc, generated by tools/native_gfx.py for each combiner key in combiners.txt: the stages are
//     constants (CMB_N stages, CMB_K<i>/CMB_L<i> below), the compiler folds the rest away;
//   - fs_vp_stage.sc, fs_vp_stage5.sc, fs_vp_stage3.sc: the generic combiner, the stages read from u_pddiFrag[6..13]
//     (any key; the one for keys without a generated program and for the vertex programs with fewer outputs).
// bgfx pairs a vertex and a fragment shader only when the fragment shader's inputs are exactly the vertex shader's
// outputs, so each output set has its own: all seven (ff, skin, skin_onebone), five (refract, skin_refract: no
// v_texcoord2/3), three (simple_proximity: no specular, one uv set): FS_UV_SETS and FS_NO_SPECULAR say which.
//
// Uniforms (bgfx_draw.cpp sets them):
//   u_pddiFrag[0]   x: alpha reference (0..255), y: alpha compare (pddi enum; < 0: no test), z: add specular
//   u_pddiFrag[1]   the fog colour (w: 1 when fog is on)
//   u_pddiFrag[2]   x: fog start, y: fog end (on the vertex output's fog depth)
//   u_pddiFrag[3]   the texture factor (D3DRS_TEXTUREFACTOR)
//   u_pddiFrag[4]   xy, zw: stage 0, 1 texture coordinate scale (1 / size for linear textures: their coordinates
//                   are in texels, the NV2A's rule; 1 otherwise); u_pddiFrag[5]: stages 2, 3
//   u_pddiFrag[14]  xy, zw: stage 0, 1 texture coordinate offset (after the scale: 0, or v -> 1 - v for a copy of a
//                   render target where targets have the origin at the bottom left, G5); u_pddiFrag[15]: stages 2, 3
//   u_pddiFrag[6 + 2i]  stage i (generic combiner): colour op, colour arg 1, colour arg 2, alpha op
//   u_pddiFrag[7 + 2i]  alpha arg 1, alpha arg 2, result register (1 current, 5 temp)
// Ops and arguments are the Xbox D3D values (bgfx_pddi.h, bgfxContext::Stage): op 1 disable .. 24 lerp; argument
// 0 diffuse, 1 current, 2 texture, 3 factor, 4 specular, 5 temp, + 16 complement, + 32 alpha replicate.

SAMPLER2D(s_pddiTex0, 0);
SAMPLER2D(s_pddiTex1, 1);
SAMPLER2D(s_pddiTex2, 2);
SAMPLER2D(s_pddiTex3, 3);
uniform vec4 u_pddiFrag[16];

#ifndef FS_UV_SETS
#define FS_UV_SETS 4
#endif

// pddi compare (the game's table 0x4d3a6c): 0 never 1 always 2 less 3 lequal 4 greater 5 gequal 6 equal 7 notequal
bool passes(int f, float a, float r)
{
    if (f == 0) return false;
    if (f == 2) return a < r;
    if (f == 3) return a <= r;
    if (f == 4) return a > r;
    if (f == 5) return a >= r;
    if (f == 6) return a == r;
    if (f == 7) return a != r;
    return true;
}

vec4 cmbArg(float a, vec4 diffuse, vec4 current, vec4 tex, vec4 tf, vec4 spec, vec4 temp)
{
    float sel = mod(a, 16.0);
    vec4 v = temp;
    if (sel < 0.5) v = diffuse;
    else if (sel < 1.5) v = current;
    else if (sel < 2.5) v = tex;
    else if (sel < 3.5) v = tf;
    else if (sel < 4.5) v = spec;
    float mods = floor(a / 16.0 + 0.001);
    if (mod(mods, 2.0) > 0.5) v = vec4_splat(1.0) - v;          // complement
    if (mods > 1.5) v = v.wwww;                                  // alpha replicate
    return v;
}

// one D3DTOP (Xbox numbering) on two arguments (a0: D3DTSS_COLORARG0, which the game leaves at current)
vec4 cmbOp(float op, vec4 a1, vec4 a2, vec4 a0, vec4 diffuse, vec4 current, vec4 tex, vec4 tf)
{
    if (op < 2.5) return a1;                                    // 2 selectarg1 (1 disable: the caller stops)
    if (op < 3.5) return a2;                                    // 3 selectarg2
    if (op < 4.5) return a1 * a2;                               // 4 modulate
    if (op < 5.5) return a1 * a2 * 2.0;                         // 5 modulate2x
    if (op < 6.5) return a1 * a2 * 4.0;                         // 6 modulate4x
    if (op < 7.5) return a1 + a2;                               // 7 add
    if (op < 8.5) return a1 + a2 - 0.5;                         // 8 addsigned
    if (op < 9.5) return (a1 + a2 - 0.5) * 2.0;                 // 9 addsigned2x
    if (op < 10.5) return a1 - a2;                              // 10 subtract
    if (op < 11.5) return a1 + a2 - a1 * a2;                    // 11 addsmooth
    if (op < 12.5) return mix(a2, a1, diffuse.w);               // 12 blenddiffusealpha
    if (op < 13.5) return mix(a2, a1, current.w);               // 13 blendcurrentalpha
    if (op < 14.5) return mix(a2, a1, tex.w);                   // 14 blendtexturealpha
    if (op < 15.5) return mix(a2, a1, tf.w);                    // 15 blendfactoralpha
    if (op < 16.5) return a1 + a2 * (1.0 - tex.w);              // 16 blendtexturealphapm
    if (op < 17.5) return a1;                                   // 17 premodulate (unused by the game)
    if (op < 18.5) return vec4(a1.xyz + a2.xyz * a1.w, a1.w);   // 18 modulatealpha_addcolor
    if (op < 19.5) return vec4(a1.xyz * a2.xyz + a1.w, a1.w);   // 19 modulatecolor_addalpha
    if (op < 20.5) return vec4(a1.xyz + a2.xyz * (1.0 - a1.w), a1.w);   // 20 modulateinvalpha_addcolor
    if (op < 21.5) return vec4((vec3_splat(1.0) - a1.xyz) * a2.xyz + a1.w, a1.w);   // 21 modulateinvcolor_addalpha
    if (op < 22.5) return vec4_splat(saturate(4.0 * dot(a1.xyz - 0.5, a2.xyz - 0.5)));   // 22 dotproduct3
    if (op < 23.5) return a0 + a1 * a2;                         // 23 multiplyadd
    if (op < 24.5) return a0 * a1 + (vec4_splat(1.0) - a0) * a2;   // 24 lerp
    return a1;                                                  // 25/26 bump mapping (unused by the data)
}

// stage k = (colour op, colour arg 1, colour arg 2, alpha op), l = (alpha arg 1, alpha arg 2, result, -)
void cmbStage(vec4 k, vec4 l, vec4 tex, vec4 diffuse, vec4 spec, vec4 tf, inout vec4 current, inout vec4 temp)
{
    vec4 c1 = cmbArg(k.y, diffuse, current, tex, tf, spec, temp);
    vec4 c2 = cmbArg(k.z, diffuse, current, tex, tf, spec, temp);
    vec4 a1 = cmbArg(l.x, diffuse, current, tex, tf, spec, temp);
    vec4 a2 = cmbArg(l.y, diffuse, current, tex, tf, spec, temp);
    vec3 rgb = saturate(cmbOp(k.x, c1, c2, current, diffuse, current, tex, tf).xyz);
    float a = saturate(cmbOp(k.w, a1, a2, current, diffuse, current, tex, tf).w);
    if (l.z > 2.5)
        temp = vec4(rgb, a);
    else
        current = vec4(rgb, a);
}

void main()
{
#ifdef FS_TWO_SIDED
    // two-sided lighting (G5, vs_vp_ff2s): the back face's colours on back faces
    vec4 diffuse = gl_FrontFacing ? v_color0 : v_bcolor0;
    vec4 spec = gl_FrontFacing ? v_color1 : v_bcolor1;
#else
    vec4 diffuse = v_color0;
#ifdef FS_NO_SPECULAR
    vec4 spec = vec4(0.0, 0.0, 0.0, 0.0);
#else
    vec4 spec = v_color1;
#endif
#endif
    vec4 tf = u_pddiFrag[3];
    vec4 current = diffuse;
    vec4 temp = vec4(0.0, 0.0, 0.0, 0.0);
    vec2 uv0 = v_texcoord0.xy * u_pddiFrag[4].xy + u_pddiFrag[14].xy;
#if FS_UV_SETS > 1
    vec2 uv1 = v_texcoord1.xy * u_pddiFrag[4].zw + u_pddiFrag[14].zw;
#else
    vec2 uv1 = vec2(0.0, 0.0);
#endif
#if FS_UV_SETS > 2
    vec2 uv2 = v_texcoord2.xy * u_pddiFrag[5].xy + u_pddiFrag[15].xy;
    vec2 uv3 = v_texcoord3.xy * u_pddiFrag[5].zw + u_pddiFrag[15].zw;
#else
    vec2 uv2 = vec2(0.0, 0.0);
    vec2 uv3 = vec2(0.0, 0.0);
#endif
#ifdef CMB_N
#if CMB_N > 0
    cmbStage(CMB_K0, CMB_L0, texture2D(s_pddiTex0, uv0), diffuse, spec, tf, current, temp);
#endif
#if CMB_N > 1
    cmbStage(CMB_K1, CMB_L1, texture2D(s_pddiTex1, uv1), diffuse, spec, tf, current, temp);
#endif
#if CMB_N > 2
    cmbStage(CMB_K2, CMB_L2, texture2D(s_pddiTex2, uv2), diffuse, spec, tf, current, temp);
#endif
#if CMB_N > 3
    cmbStage(CMB_K3, CMB_L3, texture2D(s_pddiTex3, uv3), diffuse, spec, tf, current, temp);
#endif
#else
    vec4 t0 = texture2D(s_pddiTex0, uv0);
    vec4 t1 = texture2D(s_pddiTex1, uv1);
    vec4 t2 = texture2D(s_pddiTex2, uv2);
    vec4 t3 = texture2D(s_pddiTex3, uv3);
    if (u_pddiFrag[6].x > 1.5) {
        cmbStage(u_pddiFrag[6], u_pddiFrag[7], t0, diffuse, spec, tf, current, temp);
        if (u_pddiFrag[8].x > 1.5) {
            cmbStage(u_pddiFrag[8], u_pddiFrag[9], t1, diffuse, spec, tf, current, temp);
            if (u_pddiFrag[10].x > 1.5) {
                cmbStage(u_pddiFrag[10], u_pddiFrag[11], t2, diffuse, spec, tf, current, temp);
                if (u_pddiFrag[12].x > 1.5)
                    cmbStage(u_pddiFrag[12], u_pddiFrag[13], t3, diffuse, spec, tf, current, temp);
            }
        }
    }
#endif
    vec4 c = current;
    if (u_pddiFrag[0].z > 0.5)
        c.xyz = c.xyz + spec.xyz;
    int f = int(u_pddiFrag[0].y);
    if (f >= 0 && !passes(f, floor(saturate(c.w) * 255.0 + 0.5), u_pddiFrag[0].x))
        discard;
    if (u_pddiFrag[1].w > 0.5) {
        float range = u_pddiFrag[2].y - u_pddiFrag[2].x;
        float k = range != 0.0 ? saturate((u_pddiFrag[2].y - v_fog) / range) : 1.0;
        c.xyz = mix(u_pddiFrag[1].xyz, c.xyz, k);
    }
    gl_FragColor = saturate(c);
}
